CREATE OR REPLACE FUNCTION private.journey_notice_evidence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $fn$ declare j public.onboarding_journeys; begin select * into j from public.onboarding_journeys where client_id=new.client_id; if j.privacy_body is not null then if tg_table_name='legal_consents' then if new.visible_content is distinct from j.privacy_body or new.document_version is distinct from j.privacy_version or new.details->>'health_data_explicit_consent' is distinct from 'true' then raise exception 'Accept the enrolled privacy notice and explicit health-data consent'; end if; if j.signed_at is null or lower(trim(new.signature_name)) is distinct from lower(trim(j.signature_name)) then raise exception 'Use the same legal name as your signed agreement'; end if; if auth.uid() is distinct from (select c.profile_id from public.clients c where c.id=new.client_id) then raise exception 'The client must provide their own privacy consent' using errcode='42501';end if; else if new.version<3 then raise exception 'Complete the current coaching profile';end if;end if;end if;return new;end $fn$;
